ALTER TABLE public.profiles ADD COLUMN alias_normalizado text;
UPDATE public.profiles SET alias_normalizado = lower(btrim(alias)) WHERE lower(btrim(alias)) <> 'colaborador' AND id IN (SELECT min(id::text)::uuid FROM public.profiles GROUP BY lower(btrim(alias)));
CREATE UNIQUE INDEX profiles_alias_normalizado_unique ON public.profiles(alias_normalizado);
CREATE OR REPLACE FUNCTION public.validar_alias() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.alias IS DISTINCT FROM OLD.alias OR (NEW.alias_normalizado IS DISTINCT FROM OLD.alias_normalizado AND NEW.alias_normalizado IS NOT NULL) THEN IF length(btrim(NEW.alias)) < 2 OR length(btrim(NEW.alias)) > 20 THEN RAISE EXCEPTION 'El alias debe tener entre 2 y 20 caracteres'; END IF; NEW.alias := btrim(NEW.alias); NEW.alias_normalizado := lower(NEW.alias); END IF; RETURN NEW; END $$;
CREATE TRIGGER validar_alias_update BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validar_alias();
CREATE OR REPLACE FUNCTION public.alias_disponible(_alias text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT length(btrim(_alias)) BETWEEN 2 AND 20 AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE alias_normalizado = lower(btrim(_alias)) AND id <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid)) $$;
REVOKE ALL ON FUNCTION public.alias_disponible(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.alias_disponible(text) TO authenticated;
CREATE TABLE public.estados_usuario (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, estado jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.estados_usuario TO authenticated;
GRANT ALL ON public.estados_usuario TO service_role;
ALTER TABLE public.estados_usuario ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Solo mi estado" ON public.estados_usuario FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
DROP POLICY "Responsable ve encuestas" ON public.encuestas;
DROP POLICY "Responsable ve tarjetas" ON public.tarjetas;
DROP POLICY "Responsable marca reenviada" ON public.tarjetas;
DROP POLICY "Ver mi perfil, compañero o colaboradores" ON public.profiles;
CREATE POLICY "Perfil propio o vinculado" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id OR companero_id = auth.uid() OR mentor_id = auth.uid());
DROP POLICY "Ver progreso propio, del compañero o como mentor" ON public.progreso_pasos;
CREATE POLICY "Progreso propio o vinculado" ON public.progreso_pasos FOR SELECT TO authenticated USING (auth.uid() = user_id OR EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = progreso_pasos.user_id AND (p.mentor_id = auth.uid() OR p.companero_id = auth.uid())));
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'colaborador') ON CONFLICT DO NOTHING; RETURN NEW; END $$;